    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Generate cache key
            try:
                k = key(*args, **kwargs)
            except Exception as e:
                raise RuntimeError(f"Key function raised an exception: {e}") from e

            # Helper to get from cache
            def get_from_cache():
                if hasattr(cache, "__contains__") and k in cache:
                    return cache[k]
                if hasattr(cache, "get"):
                    val = cache.get(k)
                    if val is not None:
                        return val
                raise KeyError

            # Helper to set cache
            def set_in_cache(value):
                if hasattr(cache, "__setitem__"):
                    cache[k] = value
                elif hasattr(cache, "set"):
                    cache.set(k, value)
                else:
                    raise AttributeError("Cache object does not support setting items")

            # Access cache with optional lock
            if lock is not None:
                try:
                    with lock:
                        try:
                            return get_from_cache()
                        except KeyError:
                            result = func(*args, **kwargs)
                            set_in_cache(result)
                            return result
                except Exception as e:
                    raise RuntimeError(f"Cache access with lock failed: {e}") from e
            else:
                try:
                    return get_from_cache()
                except KeyError:
                    result = func(*args, **kwargs)
                    set_in_cache(result)
                    return result

